Lemma geo_1RB1LD_1LC1RA_0LC0LD_0RA0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LD_1LC1RA_0LC0LD_0RA0RB) = lift (Cc (Pos.succ p)).
