Lemma fire_1RB1LD_1LC1RA_0RB0LC_0LB0LD : forall t, ~ In t pins_1RB1LD_1LC1RA_0RB0LC_0LB0LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
