    apply (lap_of_run tm Cc true true cho_1RB1LD_1LC1RB_0RA1LA_0RC0LC B0_1RB1LD_1LC1RB_0RA1LA_0RC0LC B1_1RB1LD_1LC1RB_0RA1LA_0RC0LC 6 22 p j' [] []).
    + exact run_ovf_1RB1LD_1LC1RB_0RA1LA_0RC0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LD_1LC1RB_0RA1LA_0RC0LC p j' E).
    + exact (geo_1RB1LD_1LC1RB_0RA1LA_0RC0LC p j' E).
