(** ** Bootstrap *)

Lemma boot_1RB1LD_1LC1RB_0RA1LA_0RC0LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 30.
  assert (H : match csteps tm 30 c0 with
