Lemma geo_1RB1LD_1LC1RB_0RA1LA_0RD0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LD_1LC1RB_0RA1LA_0RD0LC) = lift (Cc (Pos.succ p)).
