Lemma fire_1RB1LD_1LC1RB_0RA1LA_0RD0LC : forall t, ~ In t pins_1RB1LD_1LC1RB_0RA1LA_0RD0LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
