    apply (lap_of_run tm Cc true true cho_1RB1LD_1LC1RB_0RA1LA_1RA0LC B0_1RB1LD_1LC1RB_0RA1LA_1RA0LC B1_1RB1LD_1LC1RB_0RA1LA_1RA0LC 6 24 p j' [] []).
