    apply (lap_of_run tm Cc true true cho_1RB1LD_1LC1RB_0RB1LA_1LC0LC B0_1RB1LD_1LC1RB_0RB1LA_1LC0LC B1_1RB1LD_1LC1RB_0RB1LA_1LC0LC 6 22 p j' [] []).
