(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LD_1LC1RB_1LA1LA_0RB0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_110_111_111 q0 ++ [S0]) [] j A0_1RB1LD_1LC1RB_1LA1LA_0RB0LC.
