  - destruct (lapi_1RB1LD_1LC1RB_1LA1LA_0RB0LC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LD_1LC1RB_1LA1LA_0RB0LC B0_1RB1LD_1LC1RB_1LA1LA_0RB0LC B1_1RB1LD_1LC1RB_1LA1LA_0RB0LC 6 20 p j' [] []).
    + exact run_ovf_1RB1LD_1LC1RB_1LA1LA_0RB0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LD_1LC1RB_1LA1LA_0RB0LC p j' E).
    + exact (geo_1RB1LD_1LC1RB_1LA1LA_0RB0LC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LD_1LC1RB_1LA1LA_0RB0LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
