  unfold Cc_1RB1LD_1LC1RB_1LA1RC_0RA0LD, cden, P0_1RB1LD_1LC1RB_1LA1RC_0RA0LD, P1_1RB1LD_1LC1RB_1LA1RC_0RA0LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1LD_1LC1RB_1LA1RC_0RA0LD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1LD_1LC1RB_1LA1RC_0RA0LD p q0 E) as (HA & HB).
    exists (0 * 0 + 8), (cden (Dp q0 ++ [S0]) [] 0 Z1_1RB1LD_1LC1RB_1LA1RC_0RA0LD).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chz_1RB1LD_1LC1RB_1LA1RC_0RA0LD Z0_1RB1LD_1LC1RB_1LA1RC_0RA0LD Z1_1RB1LD_1LC1RB_1LA1RC_0RA0LD 0 8
             run_z_1RB1LD_1LC1RB_1LA1RC_0RA0LD (Dp q0 ++ [S0]) [] 0
             ltac:(discriminate) ltac:(reflexivity)).
  - destruct (gp_1RB1LD_1LC1RB_1LA1RC_0RA0LD p j' q0 E) as (HA & HB).
    exists (4 * j' + 12), (cden (Dp q0 ++ [S0]) [] j' P1_1RB1LD_1LC1RB_1LA1RC_0RA0LD).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chp_1RB1LD_1LC1RB_1LA1RC_0RA0LD P0_1RB1LD_1LC1RB_1LA1RC_0RA0LD P1_1RB1LD_1LC1RB_1LA1RC_0RA0LD 4 12
             run_p_1RB1LD_1LC1RB_1LA1RC_0RA0LD (Dp q0 ++ [S0]) [] j'
             ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB1LD_1LC1RB_1LA1RC_0RA0LD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LD_1LC1RB_1LA1RC_0RA0LD.
