Lemma fire_1RB1LD_1LC1RB_1LA1RC_0RB0LA : forall t, ~ In t pins_1RB1LD_1LC1RB_1LA1RC_0RB0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
