  - (* D0: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB1LD_1LC1RB_1LA1RC_0RB0LA (StD, S0)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB1LD_1LC1RB_1LA1RC_0RB0LA [SWin 2; SCycL 2 0; SWin 4; SCycR 2; SWin 1; SWinR 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LD_1LC1RB_1LA1RC_0RB0LA [SWin 2; SCycL 2 0; SWin 5] (StD, S1) ltac:(vm_compute; reflexivity)
