    apply (fire_via_ovf_lift tm Cc lapil_1RB1LD_1LC1RC_0LA1RB_1LA0RB (StB, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LD_1LC1RC_0LA1RB_1LA0RB [SRotL 1; SWin 1; SCycL 2 0; SWinL 4; SCycR 2; SWin 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LD_1LC1RC_0LA1RB_1LA0RB
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LD_1LC1RC_0LA1RB_1LA0RB
      with (l := []).
    vm_compute; reflexivity.
  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LD_1LC1RC_0LA1RB_1LA0RB (StC, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LD_1LC1RC_0LA1RB_1LA0RB [SRotL 1; SWin 1; SCycL 2 0; SWinL 4] (StC, S1) ltac:(vm_compute; reflexivity)
