Lemma fireo_1RB1LD_1LC1RC_0LD0RB_0LA1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LD_1LC1RC_0LD0RB_0LA1LA = Some t ->
