  apply (fire_via_fill tm Cc Cin lapin_1RB1LD_1LC1RC_0LD0RB_0LA1LA t p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_1RB1LD_1LC1RC_0LD0RB_0LA1LA). split;
      [| exact (gbo_1RB1LD_1LC1RC_0LD0RB_0LA1LA j)].
