(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LD_1LC1RC_0LD0RB_0LA1LA : forall t, ~ In t pins_1RB1LD_1LC1RC_0LD0RB_0LA1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LD_1LC1RC_0LD0RB_0LA1LA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LD_1LC1RC_0LD0RB_0LA1LA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LD_1LC1RC_0LD0RB_0LA1LA (StA, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LD_1LC1RC_0LD0RB_0LA1LA [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LD_1LC1RC_0LD0RB_0LA1LA (StB, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LD_1LC1RC_0LD0RB_0LA1LA [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 3] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LD_1LC1RC_0LD0RB_0LA1LA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LD_1LC1RC_0LD0RB_0LA1LA
      with (l := []).
    vm_compute; reflexivity.
  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LD_1LC1RC_0LD0RB_0LA1LA (StC, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LD_1LC1RC_0LD0RB_0LA1LA [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 4] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LD_1LC1RC_0LD0RB_0LA1LA (StD, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LD_1LC1RC_0LD0RB_0LA1LA [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1LD_1LC1RC_0LD0RB_0LA1LA
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB1LD_1LC1RC_0LD0RB_0LA1LA : NeverQuasiHaltsTr tm_1RB1LD_1LC1RC_0LD0RB_0LA1LA.
Proof.
