    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LD_1RC0LA_1LA0LD_1RB0RB
      with (l := [SWin 1; SWin 2; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LD_1RC0LA_1LA0LD_1RB0RB
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LD_1RC0LA_1LA0LD_1RB0RB
      with (l := [SWin 1; SWin 2; SCycL 3 0; SWin 2; SCycR 3; SWin 1]).
