Definition chb_1RB1LD_1RC0LB_1LA0RB_1RC0LA : list lstep := [SWinR 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_boot_1RB1LD_1RC0LB_1LA0RB_1RC0LA : srun tm true true chb_1RB1LD_1RC0LB_1LA0RB_1RC0LA B0_1RB1LD_1RC0LB_1LA0RB_1RC0LA = Some (BB1_1RB1LD_1RC0LB_1LA0RB_1RC0LA, 4, 8).
