Lemma geo_1RB1LD_1RC0LB_1LA0RB_1RC0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LD_1RC0LB_1LA0RB_1RC0LA) = lift (Cc (Pos.succ p)).
