(** ** The lap *)

Lemma lap_1RB1LD_1RC0LB_1LA0RC_1LB0LB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
