  - destruct (lapi_1RB1LD_1RC0LB_1LA0RC_1LB0LB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LD_1RC0LB_1LA0RC_1LB0LB p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LD_1RC0LB_1LA0RC_1LB0LB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
