Lemma gsi_1RB1LD_1RC0LB_1LA0RD_0RC1RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_010_110_1 q0 ++ [S0]) [] j A0_1RB1LD_1RC0LB_1LA0RD_0RC1RB.
Proof.
  intros p j q0 E. destruct (Alph_010_110_1.cview_some_Alph_010_110_1 p j q0 E) as (H1 & _).
  unfold Cc_1RB1LD_1RC0LB_1LA0RD_0RC1RB, cden, A0_1RB1LD_1RC0LB_1LA0RD_0RC1RB; cbn [c_st c_l c_h c_r].
