  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S1;S0;S0] where the anchor has [S1] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB1LD_1RC0LB_1LA0RD_0RC1RB : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_010_110_1 q0 ++ [S0]) [] j A1_1RB1LD_1RC0LB_1LA0RD_0RC1RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_010_110_1.cview_some_Alph_010_110_1 p j q0 E) as (_ & H2).
  unfold Cc_1RB1LD_1RC0LB_1LA0RD_0RC1RB, cden, A1_1RB1LD_1RC0LB_1LA0RD_0RC1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
