Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1LD_1RC0RB_0LC0LD_1LA1LD t p (pow2 j)).
  - exists (4 * j + 6), (cden [] [] j BB1_1RB1LD_1RC0RB_0LC0LD_1LA1LD). split;
      [| exact (gbo_1RB1LD_1RC0RB_0LC0LD_1LA1LD j)].
