(** ** The lap *)

Lemma lap_1RB1LD_1RC0RB_1LA1LD_1LA0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
