  - destruct (lapi_1RB1LD_1RC0RB_1LA1LD_1LA0LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LD_1RC0RB_1LA1LD_1LA0LC B0_1RB1LD_1RC0RB_1LA1LD_1LA0LC B1_1RB1LD_1RC0RB_1LA1LD_1LA0LC 4 10 p j' [] []).
    + exact run_ovf_1RB1LD_1RC0RB_1LA1LD_1LA0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LD_1RC0RB_1LA1LD_1LA0LC p j' E).
    + exact (geo_1RB1LD_1RC0RB_1LA1LD_1LA0LC p j' E).
    + lia.
