Lemma gz_1RB1LD_1RC0RB_1LA1RD_1LC0LA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] 0 Z0_1RB1LD_1RC0RB_1LA1RD_1LC0LA /\
  lift (cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] 0 Z1_1RB1LD_1RC0RB_1LA1RD_1LC0LA) = lift (Cc (Pos.succ p)).
Proof.
