Lemma gsi_1RB1LD_1RC0RB_1LD1LD_1LA0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Bp q0 ++ [S0]) [] j A0_1RB1LD_1RC0RB_1LD1LD_1LA0LC.
